<script setup lang="ts">
import { computed, ref } from 'vue'
import CameraScene from './CameraScene.vue'
import SwitchingOverview from './SwitchingOverview.vue'
import { hexBytes } from '../protocol/pelcoD'
import { busDiagnostics, type BusSettings } from '../simulation/serialBus'
import { createSimulatedCamera, maxCameras, normalizeCameraConfig, type CameraConfig, type SimulatedCamera } from '../simulation/cameras'
import { isAppliedDelivery, type CaptureEntry } from '../simulation/history'
import { baudRates, type Switcher } from '../simulation/switcher'

const props = defineProps<{ cameras: SimulatedCamera[]; switchers: Switcher[]; entries: CaptureEntry[]; settings: BusSettings; pending: number; storageError: string }>()
const emit = defineEmits<{ cameras: [items: CameraConfig[]]; controls: [id: string]; switchers: []; stop: [] }>()
const editor = ref<HTMLDialogElement>()
const draft = ref<CameraConfig[]>([])
const editorError = ref('')
const historyFilter = ref('applied')
const diagnostics = computed(() => busDiagnostics(props.settings, props.switchers))
const history = computed(() => props.entries.filter(item => historyFilter.value === 'all' || item.deliveries.some(isAppliedDelivery)))
const appliedCount = computed(() => props.entries.filter(item => item.deliveries.some(isAppliedDelivery)).length)
const issueCount = computed(() => props.entries.filter(item => item.issues.some(issue => issue.severity !== 'info')).length)
const configurations = () => props.cameras.map(({ state, ...config }) => ({ ...config }))
const displayedPan = (camera: SimulatedCamera) => ((camera.state.pan - camera.state.zeroPan) % 360 + 360) % 360
function tone(entry: CaptureEntry) { return entry.issues.some(item => item.severity === 'error') ? 'error' : entry.issues.some(item => item.severity === 'warning') ? 'warning' : entry.deliveries.some(isAppliedDelivery) ? 'success' : 'neutral' }
function nextCamera(items: CameraConfig[]) {
  const used = new Set([...items.map(item => item.address), ...props.switchers.map(item => item.address)])
  const address = Array.from({ length: 255 }, (_, i) => i + 1).find(value => !used.has(value)) ?? 1
  const { state, ...config } = createSimulatedCamera(address, `Camera ${items.length + 1}`)
  return config
}
function addCamera() { if (props.cameras.length < maxCameras) emit('cameras', [...configurations(), nextCamera(props.cameras)]) }
function openEditor() { draft.value = configurations(); editorError.value = ''; editor.value?.showModal() }
function save() {
  const valid = draft.value.map(normalizeCameraConfig)
  if (valid.some(item => !item) || valid.length < 1 || valid.length > maxCameras) { editorError.value = 'Configure one to four cameras with serial addresses 1–255.'; return }
  emit('cameras', valid as CameraConfig[]); editor.value?.close()
}
</script>

<template>
  <section class="simulator-overview" role="tabpanel" aria-labelledby="overview-tab">
    <div class="overview-heading"><div><h1>System overview</h1><span><i class="status-dot"></i> {{ cameras.length }} / 4 cameras · {{ switchers.length }} switchers · one serial bus</span></div><div class="overview-actions"><button class="button secondary" @click="openEditor">Configure cameras</button><button class="button danger-outline" @click="emit('stop')"><span class="stop-square"></span> Stop all</button></div></div>
    <p v-if="storageError" class="inline-warning" role="alert">{{ storageError }}</p>
    <div class="overview-cameras" :style="{ '--camera-columns': Math.min(cameras.length + (cameras.length < maxCameras ? 1 : 0), 4) }">
      <article v-for="camera in cameras" :key="camera.id" class="panel overview-camera-card" :aria-label="`${camera.name}, serial address ${camera.address}`" :data-camera-window="camera.address">
        <div class="camera-window-heading"><strong :title="camera.name">{{ camera.name }}</strong><code>ADDR {{ camera.address }}</code><button class="text-button" :aria-label="`Open controls for ${camera.name}`" @click="emit('controls', camera.id)">↗</button></div>
        <CameraScene :camera="camera.state" :show-frustum="false" compact />
        <div class="camera-window-readout"><span>PAN <b>{{ displayedPan(camera).toFixed(1) }}°</b></span><span>TILT <b>{{ camera.state.tilt.toFixed(1) }}°</b></span><span>ZOOM <b>{{ camera.state.zoom.toFixed(1) }}×</b></span><span v-if="camera.state.lampOn" class="overview-lamp">☀</span></div>
      </article>
      <button v-if="cameras.length < maxCameras" class="add-camera-window" @click="addCamera"><span>+</span><strong>Add camera window</strong><small>Independent PTZ · {{ maxCameras - cameras.length }} available</small></button>
    </div>
    <div v-if="diagnostics.length || pending" class="overview-bus-issues" role="status"><p v-for="(issue, i) in diagnostics" :key="i"><span>!</span>{{ issue.message }}</p><p v-if="pending"><span>⌁</span>{{ pending }} byte(s) waiting for a complete frame.</p></div>
    <div class="overview-bottom">
      <SwitchingOverview :switchers="switchers" @configure="emit('switchers')" />
      <section class="panel overview-history">
        <div class="panel-heading"><h2><span class="small-icon">≡</span> Action history <span class="count-badge">{{ appliedCount }}</span></h2><select v-model="historyFilter" aria-label="Overview history filter"><option value="applied">Applied actions</option><option value="all">All activity</option></select></div>
        <div class="overview-history-list">
          <details v-for="entry in history" :key="entry.id" class="overview-history-entry" :class="tone(entry)">
            <summary><div class="history-entry-top"><time>{{ entry.time }}</time><span class="result-tag" :class="tone(entry)">{{ entry.result }}</span></div><strong>{{ entry.description }}</strong><span class="history-targets">{{ entry.deliveries.filter(isAppliedDelivery).map(item => item.name).join(' · ') || 'No action applied' }}</span></summary>
            <div class="history-entry-detail"><div v-for="item in entry.deliveries.filter(isAppliedDelivery)" :key="item.id"><strong>{{ item.name }}</strong><span>{{ item.detail }}</span></div><code>{{ hexBytes(entry.bytes) }}</code><p v-for="(issue, i) in entry.issues" :key="i" :class="issue.severity">{{ issue.message }}</p><span>Source: {{ entry.source }}</span></div>
          </details>
          <div v-if="!history.length" class="overview-history-empty"><span>⌁</span><strong>{{ entries.length ? 'No applied actions yet' : 'Waiting for commands' }}</strong><p>{{ entries.length ? 'Select All activity to inspect ignored or rejected traffic.' : 'Applied camera and routing commands appear here as they arrive.' }}</p></div>
        </div>
        <div class="overview-history-footer"><span>Latest {{ entries.length }} / 200 commands</span><button v-if="issueCount" class="text-button" @click="historyFilter = 'all'">{{ issueCount }} with issues</button><span v-else>Live history</span></div>
      </section>
    </div>
    <dialog ref="editor" class="overview-camera-editor" aria-labelledby="overview-camera-editor-title"><form @submit.prevent="save"><div class="camera-editor-heading"><h3 id="overview-camera-editor-title">Configure overview cameras</h3><button type="button" class="icon-button" aria-label="Close camera configuration" @click="editor?.close()">×</button></div><p>Each window simulates its own serial address. Camera names and addresses are saved in this browser.</p><div v-for="(item, i) in draft" :key="item.id" class="camera-editor-row"><label>Camera {{ i + 1 }} name<input v-model="item.name" :aria-label="`Camera ${i + 1} name`" required maxlength="80" /></label><label>Address<input v-model.number="item.address" type="number" min="1" max="255" required :aria-label="`Camera ${i + 1} address`" /></label><label>Baud rate<select v-model.number="item.baudRate" :aria-label="`Camera ${i + 1} baud rate`"><option v-for="rate in baudRates" :key="rate" :value="rate">{{ rate }}</option></select></label><button type="button" class="text-button" :disabled="draft.length === 1" :aria-label="`Remove camera ${i + 1}`" @click="draft.splice(i, 1)">×</button></div><button type="button" class="button secondary" :disabled="draft.length >= maxCameras" @click="draft.push(nextCamera(draft))">+ Add camera</button><p class="camera-editor-note">Use addresses matching your backend. Duplicate addresses are allowed for interference checks. Changing a camera address resets its simulated position and features.</p><p v-if="editorError" class="error-message" role="alert">{{ editorError }}</p><div class="camera-editor-actions"><button type="button" class="button secondary" @click="editor?.close()">Cancel</button><button type="submit" class="button primary">Save cameras</button></div></form></dialog>
  </section>
</template>

